int reverseInteger(int x) {
    int rev = 0;
    while (x != 0) {
        int digit = x % 10;          // pop  (C++ truncates toward zero, sign follows x)
        x /= 10;
        // push is rev*10 + digit -- test for overflow BEFORE performing it
        if (rev > INT_MAX / 10 || (rev == INT_MAX / 10 && digit > 7)) return 0;
        if (rev < INT_MIN / 10 || (rev == INT_MIN / 10 && digit < -8)) return 0;
        rev = rev * 10 + digit;
    }
    return rev;
}

struct Node {
    int val;
    Node* next;
    Node* random;
    Node(int v) : val(v), next(nullptr), random(nullptr) {}
};

Node* copyRandomList(Node* head) {
    if (!head) return nullptr;
    // 1. weave: A -> A' -> B -> B' -> ...
    for (Node* p = head; p; p = p->next->next) {
        Node* clone = new Node(p->val);
        clone->next = p->next;
        p->next = clone;
    }
    // 2. randoms: the clone of p->random sits right after it
    for (Node* p = head; p; p = p->next->next)
        p->next->random = p->random ? p->random->next : nullptr;
    // 3. unweave, restoring the original list
    Node* newHead = head->next;
    for (Node* p = head; p; p = p->next) {
        Node* clone = p->next;
        p->next = clone->next;
        clone->next = p->next ? p->next->next : nullptr;
    }
    return newHead;
}

