    vector<int> vals;
    unordered_map<int,int> idx;   // value -> position in vals
public:
    bool insert(int val) {
        if (idx.count(val)) return false;
        idx[val] = (int)vals.size();
        vals.push_back(val);
        return true;
    }
    bool remove(int val) {
        auto it = idx.find(val);
        if (it == idx.end()) return false;
        int pos = it->second, last = vals.back();
        vals[pos] = last;          // overwrite the hole with the tail
        idx[last] = pos;           // patch the moved element's index
        vals.pop_back();
        idx.erase(it);
        return true;
    }
    int getRandom() { return vals[rand() % vals.size()]; }
};

