import random


class RandomizedSet:
    def __init__(self):
        self.vals = []
        self.idx = {}                  # value -> position in vals

    def insert(self, val: int) -> bool:
        if val in self.idx:
            return False
        self.idx[val] = len(self.vals)
        self.vals.append(val)
        return True

    def remove(self, val: int) -> bool:
        if val not in self.idx:
            return False
        pos, last = self.idx[val], self.vals[-1]
        self.vals[pos] = last          # overwrite the hole with the tail
        self.idx[last] = pos           # patch the moved element's index
        self.vals.pop()
        del self.idx[val]
        return True

    def get_random(self) -> int:
        return random.choice(self.vals)

