vector<long long> segmentedSieve(long long L, long long R) {
    long long limit = (long long)sqrtl((long double)R) + 1;
    vector<bool> base(limit + 1, true);
    base[0] = base[1] = false;
    for (long long i = 2; i * i <= limit; ++i)
        if (base[i])
            for (long long j = i * i; j <= limit; j += i) base[j] = false;

    vector<bool> window(R - L + 1, true);
    if (L < 2) for (long long v = L; v <= min(R, 1LL); ++v) window[v - L] = false;

    for (long long p = 2; p <= limit; ++p) {
        if (!base[p]) continue;
        long long start = max(p * p, (L + p - 1) / p * p);   // first multiple >= L
        for (long long j = start; j <= R; j += p) window[j - L] = false;
    }
    vector<long long> out;
    for (long long v = L; v <= R; ++v) if (window[v - L]) out.push_back(v);
    return out;
}

