def segmented_sieve(L: int, R: int) -> list[int]:
    limit = int(R ** 0.5) + 1
    base = [True] * (limit + 1)
    base[0] = base[1] = False
    i = 2
    while i * i <= limit:
        if base[i]:
            for j in range(i * i, limit + 1, i):
                base[j] = False
        i += 1

    window = [True] * (R - L + 1)
    for v in range(L, min(R, 1) + 1):        # 0 and 1 are not prime
        window[v - L] = False

    for p in range(2, limit + 1):
        if not base[p]:
            continue
        start = max(p * p, ((L + p - 1) // p) * p)   # first multiple >= L
        for j in range(start, R + 1, p):
            window[j - L] = False
    return [v for v in range(L, R + 1) if window[v - L]]

