vector<int> closestPrimes(int left, int right) {
    int limit = (int)sqrt((double)right) + 1;
    vector<bool> base(limit + 1, true);
    base[0] = base[1] = false;
    for (int i = 2; i * i <= limit; ++i)
        if (base[i]) for (int j = i * i; j <= limit; j += i) base[j] = false;

    vector<bool> win(right - left + 1, true);
    for (int v = left; v <= min(right, 1); ++v) win[v - left] = false;
    for (int p = 2; p <= limit; ++p) {
        if (!base[p]) continue;
        long long start = max((long long)p * p, ((long long)left + p - 1) / p * p);
        for (long long j = start; j <= right; j += p) win[j - left] = false;
    }

    int prev = -1, bestA = -1, bestB = -1, bestGap = INT_MAX;
    for (int v = left; v <= right; ++v) {
        if (!win[v - left]) continue;
        if (prev != -1 && v - prev < bestGap) { bestGap = v - prev; bestA = prev; bestB = v; }
        prev = v;
        if (bestGap == 1) break;   // 2,3 is the only gap-1 pair; nothing can beat it
    }
    return {bestA, bestB};
}

