def closest_primes(left: int, right: int) -> list[int]:
    limit = int(right ** 0.5) + 1
    base = [True] * (limit + 1)
    base[0] = base[1] = False
    i = 2
    while i * i <= limit:
        if base[i]:
            for j in range(i * i, limit + 1, i):
                base[j] = False
        i += 1

    win = [True] * (right - left + 1)
    for v in range(left, min(right, 1) + 1):
        win[v - left] = False
    for p in range(2, limit + 1):
        if not base[p]:
            continue
        start = max(p * p, ((left + p - 1) // p) * p)
        for j in range(start, right + 1, p):
            win[j - left] = False

    prev, best = -1, (-1, -1)
    best_gap = float('inf')
    for v in range(left, right + 1):
        if not win[v - left]:
            continue
        if prev != -1 and v - prev < best_gap:
            best_gap, best = v - prev, (prev, v)
        prev = v
        if best_gap == 1:      # 2,3 is the only gap-1 pair
            break
    return list(best)

