class LRUCache {
    struct Node { int key, val; Node *prev, *next; };
    int cap;
    unordered_map<int, Node*> map;
    Node *head, *tail;              // sentinels: head->next = MRU, tail->prev = LRU

    void unlink(Node* n) { n->prev->next = n->next; n->next->prev = n->prev; }
    void pushFront(Node* n) {
        n->next = head->next; n->prev = head;
        head->next->prev = n; head->next = n;
    }
public:
    explicit LRUCache(int capacity) : cap(capacity) {
        head = new Node{0,0,nullptr,nullptr};
        tail = new Node{0,0,nullptr,nullptr};
        head->next = tail; tail->prev = head;
    }
    int get(int key) {
        auto it = map.find(key);
        if (it == map.end()) return -1;
        unlink(it->second); pushFront(it->second);   // touch = move to front
        return it->second->val;
    }
    void put(int key, int value) {
        auto it = map.find(key);
        if (it != map.end()) {
            it->second->val = value;
            unlink(it->second); pushFront(it->second);
            return;
        }
        if ((int)map.size() == cap) {
            Node* lru = tail->prev;
            unlink(lru); map.erase(lru->key); delete lru;
        }
        Node* n = new Node{key, value, nullptr, nullptr};
        pushFront(n); map[key] = n;
    }
};

