# Python has no equivalent bug: method lookup is ALWAYS dynamic, so the
# most-derived __del__ is the one that runs regardless of the static type.
class Base:
    def __init__(self):
        self.buf = [0] * 100
    def __del__(self):
        self.buf = None          # always reached


class Derived(Base):
    def __init__(self):
        super().__init__()
        self.extra = [0] * 1000
    def __del__(self):
        self.extra = None        # runs even when referenced as a Base
        super().__del__()


def demo() -> str:
    obj: Base = Derived()        # static annotation does not change dispatch
    return type(obj).__name__    # 'Derived' -- Python resolves at runtime
